s = input().strip()
n = int(input())

operations = []

for _ in range(n):
    operations.append(input().split())

for op in reversed(operations):
    command = op[0]

    if command == "R":
        s = s[::-1]

    elif command == "L":
        k = int(op[1])
        k %= len(s)
        s = s[-k:] + s[:-k] if k else s

    elif command == "S":
        a = int(op[1])
        b = int(op[2])

        chars = list(s)
        chars[a], chars[b] = chars[b], chars[a]
        s = "".join(chars)

    elif command == "B":
        k = int(op[1])
        size = len(s) // k

        blocks = [
            s[i * size:(i + 1) * size]
            for i in range(k)
        ]

        s = "".join(reversed(blocks))

    elif command == "P":
        pairs = [
            s[i:i + 2]
            for i in range(0, len(s), 2)
        ]

        shuffled = []

        for i in range(0, len(pairs), 2):
            shuffled.append(pairs[i + 1])
            shuffled.append(pairs[i])

        s = "".join(shuffled)

print(s)
